def features(r, c, model, decay):
    (x, y) = ((r - 7.5) / 7.5, (c - 11.5) / 11.5)
    (dr, dc) = (np.minimum(r, 15 - r), np.minimum(c, 23 - c))
    (er, ec) = (np.exp(-dr / decay), np.exp(-dc / decay))
    base = [np.ones_like(x), x, y]
    if model == 'flat':
        return np.array(base[:1]).T
    if model == 'nearest':
        base += [np.maximum(er, ec)]
    if model == 'sum':
        base += [er + ec]
    if model == 'separate':
        base += [er, ec]
    if model == 'corner':
        base += [er, ec, er * ec]
    if model == 'cross':
        base += [np.maximum(er, ec), x * y]
    return np.array(base).T
